scwin.grd_sample1_onviewchange = function (info) {
    console.log("===============onviewchange===============")
    console.log("oldValue : " + info.oldValue)
    console.log("newValue : " + info.newValue)

};

	scwin.fireDbClick = function(node){
		if( document.createEventObject ) {
			node.fireEvent('ondblclick') ;
		} else if( document.createEvent ) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function' ) {
			node.ondblclick();
		}
	}

	scwin.Dbclick = function(id){
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick (el);
	}	

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#G_'+$p.id+'grd_sample1__col3', 'key-sequence', {
			sequence: '111'
		});
	}	
	scwin.checkVal = function() {
		return window.check_nowValue == 'sdssd111';
	}		
	scwin.unitTest = function(){
		//init
		WebSquare.wUnit.start();

		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_sample1_cell_0_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_sample1_cell_0_2')");	
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");	
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_textImage_button')[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
